"""Build a standalone private raster/vector comparison from a path-only config."""
import argparse,base64,json,html
from pathlib import Path
import cv2

def load(path):return json.loads(Path(path).read_text())
def build(config,output):
 cases=[]
 for c in load(config)['cases']:
  im=cv2.imread(c['image']);h,w=im.shape[:2];factor=min(1,1600/max(h,w));preview=cv2.resize(im,(round(w*factor),round(h*factor)));ok,data=cv2.imencode('.jpg',preview,[cv2.IMWRITE_JPEG_QUALITY,88]);assert ok
  item={k:c[k]for k in ('name','note','grid')};item['preferred_method']=c.get('preferred_method',c['methods'][0]['name']);item.update(width=w,height=h,image='data:image/jpeg;base64,'+base64.b64encode(data).decode(),gt=[],gtPortals=[],methods=[])
  if c.get('reference'):
   r=load(c['reference']);g=r['resolution']['pixels_per_grid'];item['gt']=[[a['x']*g,a['y']*g,b['x']*g,b['y']*g]for line in r['line_of_sight']for a,b in zip(line,line[1:])];item['gtPortals']=[[a['x']*g,a['y']*g,b['x']*g,b['y']*g]for portal in r.get('portals',[])for a,b in zip(portal['bounds'],portal['bounds'][1:])]
  for m in c['methods']:
   geometry=load(m['walls']) if m.get('walls') else {'walls':[]};x={'name':m['name'],'walls':geometry['walls'],'metrics':None,'seconds':None,'portal_metrics':None,'portals':geometry.get('portals',[]),'ai_usage':m.get('ai_usage','Not recorded'),'note':m.get('note',''),'metric_scope':m.get('metric_scope','full_image')}
   if m.get('overlay'):
    overlay=cv2.imread(m['overlay']);assert overlay.shape[:2]==im.shape[:2];overlay=cv2.resize(overlay,(round(w*factor),round(h*factor)));ok,encoded=cv2.imencode('.jpg',overlay,[cv2.IMWRITE_JPEG_QUALITY,88]);assert ok;x['overlay']='data:image/jpeg;base64,'+base64.b64encode(encoded).decode()
   if m.get('evaluation'):
    evaluation=load(m['evaluation']);x['metrics']=evaluation['structural'];x['portal_metrics']=evaluation.get('portals')
   if m.get('inference'):x['seconds']=load(m['inference']).get('seconds')
   item['methods'].append(x)
  cases.append(item)
 payload=json.dumps(cases,separators=(',',':')).replace('</','<\\/')
 costs=load(load(config)['costs']) if load(config).get('costs') else {}
 rows=''
 for name,cost in costs.items():
  u=cost['usage'];rows+='<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in [name,cost['rounds'],f"{cost['uncached_input']:,}",f"{u['cached_input_tokens']:,}",f"{u['output_tokens']:,}",u['cache_write_input_tokens'],f"${cost['semantic_label_cost_usd']:.5f}"])+'</tr>'
 cost_html=('<section style="padding:0 24px 24px;overflow:auto"><h2>AI semantic label cost · measured task scope</h2><table><thead><tr><th>Map</th><th>Rounds</th><th>Uncached input</th><th>Cached input</th><th>Output</th><th>Cache write</th><th>USD</th></tr></thead><tbody>'+rows+'</tbody></table><p class="fine">User SOL rates per million tokens: $2 uncached input, $0.10 cached input, $10 output. AI label tasks only; research, integration and CPU excluded. No separate cache writes reported. Warm context reuse is not guaranteed in production. Frost inherited 142,976 cached / 4,124 uncached / 627 output tokens: $0.02882 measured warm-cache cost; the same 147,100 input tokens cold would cost $0.30047 in label scope. Total workflow cost is not established.</p></section>') if costs else ''
 page=HTML.replace('__DATA__',payload).replace('__COSTS__',cost_html);Path(output).write_text(page)
 print(json.dumps({'output':str(Path(output).resolve()),'cases':len(cases),'methods':sum(len(c['methods'])for c in cases),'bytes':len(page)}))
HTML='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wall extraction · private comparison</title><style>
*{box-sizing:border-box}body{margin:0;background:#10151d;color:#e2e8f0;font:15px system-ui,sans-serif}header{padding:18px 24px;background:#182231}h1{font-size:22px;margin:0 0 8px}p{margin:8px 0;color:#b8c5d6}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;padding:12px 24px;background:#1d2939}select,button{background:#101b2a;color:#f1f5f9;border:1px solid #52657b;padding:8px;border-radius:5px}label{display:flex;gap:6px;align-items:center}main{display:grid;grid-template-columns:330px 1fr;gap:16px;padding:16px}aside{background:#182231;padding:16px;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:9px 4px;text-align:right;border-bottom:1px solid #354154}th:first-child,td:first-child{text-align:left}tr.selected{background:#2d4059}tbody tr{cursor:pointer}.metric{font-size:20px;line-height:1.5;color:#eaf3ff}.green{color:#46f39a}.magenta{color:#fc6ad7}.stage{height:74vh;min-height:420px;background:#05080d;border:1px solid #44566d;border-radius:8px;overflow:hidden}svg{width:100%;height:100%;touch-action:none;cursor:grab}svg:active{cursor:grabbing}.fine{font-size:12px;line-height:1.5}#status{color:#f5cc78}h2{font-size:17px}a{color:#a7d0ff}@media(max-width:850px){main{grid-template-columns:1fr}.stage{height:65vh}aside{order:2}}
</style></head><body><header><h1>Wall extraction · private comparison</h1><p>Experimental results. Boundary proximity and visibility probes measure different failures. No 98% quality claim.</p></header><div class="controls"><label>Map <select id="case"></select></label><label>Method <select id="method"></select></label><label>Tolerance <select id="tol"><option value="0.1">0.1 grid</option><option value="0.2" selected>0.2 grid</option><option value="0.3">0.3 grid</option></select></label><label class="green"><input id="candidate" type="checkbox" checked>Candidate</label><label class="magenta"><input id="truth" type="checkbox" checked>Ground truth</label><label style="color:#ffae42"><input id="show-portals" type="checkbox" checked>Portal proposals</label><button id="fit">Fit map</button></div><main><aside><h2 id="mapname"></h2><p id="note"></p><p id="reference-status" class="fine"></p><div id="status"></div><h2 id="methodname"></h2><p id="ai-usage"></p><p id="method-note" class="fine"></p><div id="metric" class="metric"></div><p id="visibility"></p><p id="portal-quality"></p><p id="runtime"></p><h2>Compare methods</h2><table><thead><tr><th>Method / AI use</th><th>P</th><th>R</th><th>F1</th></tr></thead><tbody id="rows"></tbody></table><p class="fine">Metrics score structural walls. Candidate notes identify training and evaluation scope. Portal instances are scored separately. Colored predictions are not ground truth.</p><p class="fine">Orange spans are unverified portal proposals; cyan spans are reference portals. Wheel to zoom, drag to pan. Choose a method or table row while preserving the current view.</p></aside><section><div class="stage"><svg id="map" role="img" aria-label="Map with candidate and reference wall overlays"><image id="raster" x="0" y="0"/><image id="classifier-overlay" x="0" y="0"/><path id="gt" fill="none" stroke="#fc48d0" stroke-width="2" vector-effect="non-scaling-stroke" opacity=".9"/><path id="gt-portals" fill="none" stroke="#24caff" stroke-width="5" vector-effect="non-scaling-stroke"/><path id="doors" fill="none" stroke="#ffae42" stroke-width="4" vector-effect="non-scaling-stroke"/><path id="walls" fill="none" stroke="#30f790" stroke-width="2" vector-effect="non-scaling-stroke" opacity=".9"/></svg></div></section></main>__COSTS__<script>
const DATA=__DATA__;const $=id=>document.getElementById(id);let current=0,method=0,view=[],drag=null;const svg=$('map');
function path(lines){return lines.map(a=>'M'+a[0]+' '+a[1]+'L'+a[2]+' '+a[3]).join(' ')}
function pct(x){return x==null?'—':(100*x).toFixed(1)+'%'}
function score(m){return m.metrics?Object.entries(m.metrics[m.metric_scope]||{}).find(([k])=>Math.abs(Number(k)-DATA[current].grid*Number($('tol').value))<1e-6)?.[1]:null}
function fit(){let c=DATA[current];view=[0,0,c.width,c.height];apply()}
function apply(){svg.setAttribute('viewBox',view.join(' '))}
function update(){let c=DATA[current],m=c.methods[method],s=score(m);$('classifier-overlay').setAttribute('href',m.overlay||'');$('classifier-overlay').setAttribute('width',c.width);$('classifier-overlay').setAttribute('height',c.height);$('classifier-overlay').style.display=m.overlay&&$('candidate').checked?'':'none';$('methodname').textContent=m.name;$('ai-usage').textContent=m.ai_usage;$('method-note').textContent=m.note;$('walls').setAttribute('d',path(m.walls));$('doors').setAttribute('d',path(m.portals));$('doors').style.display=$('candidate').checked&&$('show-portals').checked?'':'none';$('gt').style.display=$('truth').checked?'':'none';$('gt-portals').style.display=$('truth').checked?'':'none';$('walls').style.display=$('candidate').checked?'':'none';$('metric').textContent=s?'Precision '+pct(s.precision)+' · Recall '+pct(s.recall):'No reference metrics';$('status').textContent=(m.metric_scope==='spatial_heldout'?'Held-out building groups · ':'Full image · ')+'Tolerance '+(c.grid*Number($('tol').value)).toFixed(0)+' pixels ('+$('tol').value+' grid)';let v=m.metric_scope==='spatial_heldout'?m.metrics?.spatial_heldout_visibility:m.metrics?.visibility;$('visibility').textContent=v?'False open '+v.false_open+' / '+v.reference_blocked+' blocked probes; false blocked '+v.false_blocked+' / '+v.reference_open+' open probes.':'Qualitative comparison only. Accuracy is unknown.';let portal=m.portal_metrics?.[m.metric_scope];$('portal-quality').textContent=portal?'Portals: '+portal.matched+' / '+portal.reference_portals+' matched; '+portal.proposals+' proposals. Precision '+pct(portal.precision)+' · Recall '+pct(portal.recall)+' (fixed 0.2-grid endpoint tolerance).':m.portals.length?'Unverified portal proposals: '+m.portals.length:'';$('runtime').textContent=(m.overlay?'Classifier overlay only; no UVTT walls':m.walls.length+' segments')+' · '+(m.seconds==null?'timing unavailable':m.seconds.toFixed(3)+' s image solver');$('rows').replaceChildren();c.methods.forEach((x,i)=>{let tr=document.createElement('tr');if(i===method)tr.className='selected';let q=score(x);[x.name+' · '+x.ai_usage,pct(q?.precision),pct(q?.recall),q?(q.f1*100).toFixed(1)+'%':'—'].forEach(t=>{let td=document.createElement('td');td.textContent=t;tr.append(td)});tr.onclick=()=>{method=i;$('method').value=String(i);update()};$('rows').append(tr)})}
function selectCase(){current=Number($('case').value);let c=DATA[current];method=Math.max(0,c.methods.findIndex(m=>m.name===c.preferred_method));$('mapname').textContent=c.name;$('note').textContent=c.note;$('raster').setAttribute('href',c.image);$('raster').setAttribute('width',c.width);$('raster').setAttribute('height',c.height);$('gt').setAttribute('d',path(c.gt));$('gt-portals').setAttribute('d',path(c.gtPortals));const hasReference=!!(c.gt.length||c.gtPortals.length);$('truth').disabled=!hasReference;$('truth').checked=hasReference;$('truth').parentElement.style.display=hasReference?'':'none';$('reference-status').textContent=hasReference?'Reference walls: magenta; reference portals: cyan.':'No ground truth supplied. All colored marks are predictions.';$('method').replaceChildren();c.methods.forEach((m,i)=>$('method').add(new Option(m.name,i)));$('method').value=String(method);fit();update()}
DATA.forEach((c,i)=>$('case').add(new Option(c.name,i)));$('case').onchange=selectCase;$('method').onchange=()=>{method=Number($('method').value);update()};['tol','truth','candidate','show-portals'].forEach(id=>$(id).onchange=update);$('fit').onclick=fit;
svg.addEventListener('wheel',e=>{e.preventDefault();let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;let q=p.matrixTransform(svg.getScreenCTM().inverse());let factor=e.deltaY>0?1.15:1/1.15;view=[q.x+(view[0]-q.x)*factor,q.y+(view[1]-q.y)*factor,view[2]*factor,view[3]*factor];apply()},{passive:false});
svg.onpointerdown=e=>{svg.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,view:[...view]}};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;svg.onpointermove=e=>{if(!drag)return;let matrix=svg.getScreenCTM();view=[drag.view[0]-(e.clientX-drag.x)/matrix.a,drag.view[1]-(e.clientY-drag.y)/matrix.d,drag.view[2],drag.view[3]];apply()};const initial=Number(new URLSearchParams(location.search).get("map")||0);if(Number.isInteger(initial)&&DATA[initial])$("case").value=String(initial);selectCase();
</script></body></html>'''
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('config');p.add_argument('output');a=p.parse_args();build(a.config,a.output)
